helpers = r'''function dstStats(row){return row&&typeof row==='object'?{...(row.stats&&typeof row.stats==='object'?row.stats:{}),...row}:{} }
function scoreLeagueStats(row){const x=dstStats(row),scoring=st.league?.scoring_settings||{};let total=0,matched=0;for(const[k,w0]of Object.entries(scoring)){const sv=maybeNum(x[k]),w=maybeNum(w0);if(sv!=null&&w!=null&&w!==0){total+=sv*w;matched++}}return matched?total:null}
function seasonPpgInfo(id,p=st.players?.[id],entry=null){if(isDstId(id,p))return{value:null,source:'none',games:null};const row=st.seasonStats.get(String(id))||null,x=dstStats(row),gp=n(field(x,['gp','games_played','games']),null),total=scoreLeagueStats(row);if(gp!=null&&gp>0&&total!=null)return{value:total/gp,source:'actual',games:gp};const e=entry||resolveModel(id,p),base=e?.base||null,projected=n(field(base,['season_fppg','projected_fppg','year1_fppg','fppg']));return{value:projected,source:projected!=null?'projected':'none',games:null}}
async function loadSeasonStats(force=false){if(!st.season)return;const fresh=st.seasonStatsSeason===+st.season&&st.seasonStats.size&&Date.now()-st.seasonStatsAt<15*60*1000;if(fresh&&!force)return;const url=`${S}/stats/nfl/regular/${st.season}?position[]=QB&position[]=RB&position[]=WR&position[]=TE&order_by=pts_ppr`,data=await liveJson(url,null);if(!data)return;const entries=Array.isArray(data)?data.map((r,i)=>[r?.player_id||String(i),r]):typeof data==='object'?Object.entries(data):[],next=new Map;for(const[key,row]of entries){const raw=row?.player_id||key,id=String(raw).replace(/^PLAYER_/,'');if(id)next.set(id,row)}if(next.size){st.seasonStats=next;st.seasonStatsSeason=+st.season;st.seasonStatsAt=Date.now()}}
function seasonStat(id,key,aliases=[]){const x=dstStats(st.seasonStats.get(String(id)));return n(field(x,[key,...aliases]))}
function profileAnalysis(id,p,m){const notes=[];if(m.projection!=null&&m.avg!=null){const d=m.projection-m.avg,a=Math.abs(d);notes.push(a<0.75?`Week ${st.week} projects very close to the current-season scoring rate.`:`Week ${st.week} projects ${f(a)} points ${d>0?'above':'below'} the current-season scoring rate, which is the clearest short-term decision signal.`)}if(m.floor!=null&&m.ceiling!=null){const span=m.ceiling-m.floor;notes.push(span>=10?`The ${f(m.floor)}–${f(m.ceiling)} range is relatively wide, so this profile carries meaningful weekly volatility.`:`The ${f(m.floor)}–${f(m.ceiling)} range is relatively compact, giving this projection a steadier weekly shape.`)}const e=resolveModel(id,p),rank=n(field(e?.base,['dynasty_rank','model_dynasty_rank','overall_dynasty_rank']));if(m.dynasty!=null)notes.push(rank!=null?`Long-term model value is ${fi(m.dynasty)} with a dynasty rank of #${fi(rank)}.`:`Long-term model value is ${fi(m.dynasty)} on the site's player/pick currency.`);const inj=p?.injury_status||p?.status;if(inj&&!['Active','ACT'].includes(String(inj)))notes.push(`Current player status: ${inj}. Availability should be checked before locking the lineup.`);return notes}
function playerProfile(){const id=st.profile;if(!id)return'';const p=st.players?.[id]||{},dst=isDstId(id,p),m=model(id,p),e=resolveModel(id,p),b=e?.base||{},rank=n(field(b,['dynasty_rank','model_dynasty_rank','overall_dynasty_rank'])),y3=n(field(b,['year3_fppg'])),career=n(field(b,['dynasty_career_projected_points','career_projected_points'])),ageV=n(p?.age??field(b,['age'])),gp=m.avgGames,avgSub=m.avgSource==='actual'?`Actual · ${gp||0} GP`:m.avgSource==='projected'?'Projected baseline':'Unavailable',pos=String(p?.position||field(b,['position'])||'').toUpperCase(),stats=[];if(pos==='QB'){stats.push(['Pass Att',seasonStat(id,'pass_att')],['Pass Yds',seasonStat(id,'pass_yd',['pass_yds'])],['Pass TD',seasonStat(id,'pass_td')],['Rush Att',seasonStat(id,'rush_att')])}else if(pos==='RB'){stats.push(['Carries',seasonStat(id,'rush_att')],['Rush Yds',seasonStat(id,'rush_yd',['rush_yds'])],['Targets',seasonStat(id,'rec_tgt',['targets'])],['Receptions',seasonStat(id,'rec')])}else if(['WR','TE'].includes(pos)){stats.push(['Targets',seasonStat(id,'rec_tgt',['targets'])],['Receptions',seasonStat(id,'rec')],['Rec Yds',seasonStat(id,'rec_yd',['rec_yds'])],['Rec TD',seasonStat(id,'rec_td')])}const notes=profileAnalysis(id,p,m);return`<div class="profile-backdrop" data-profile-backdrop><aside class="player-profile" role="dialog" aria-modal="true" aria-label="${esc(pname(id))} player profile"><div class="profile-grabber"></div><div class="profile-head"><img class="profile-image ${dst?'dst-logo':''}" src="${assetImage(id,p)}" alt="" onerror="this.style.visibility='hidden'"><div class="profile-title"><div class="eyebrow">Player card</div><h2>${esc(pname(id))}</h2><div class="player-meta">${esc(pos||'—')} · ${esc(p?.team||field(b,['team'])||'FA')}${ageV!=null?` · Age ${f(ageV,0)}`:''}</div><div class="player-opp">${esc(m.opp||'Matchup unavailable')}</div></div><button class="profile-close" data-a="closeProfile" aria-label="Close player profile">×</button></div><div class="profile-metrics"><div class="profile-metric"><span>Week ${st.week}</span><strong>${f(m.projection)}</strong><small>Model projection</small></div><div class="profile-metric"><span>Season PPG</span><strong>${f(m.avg)}</strong><small>${esc(avgSub)}</small></div><div class="profile-metric"><span>Range</span><strong>${f(m.floor)}–${f(m.ceiling)}</strong><small>Floor–ceiling</small></div><div class="profile-metric"><span>Dynasty</span><strong>${m.dynasty!=null?fi(m.dynasty):'—'}</strong><small>${rank!=null?`Rank #${fi(rank)}`:'Model value'}</small></div></div>${stats.some(([,v])=>v!=null)?`<div class="profile-section"><div class="profile-section-title">Current season production</div><div class="profile-stat-grid">${stats.map(([k,v])=>`<div><span>${k}</span><strong>${v==null?'—':f(v,0)}</strong></div>`).join('')}</div></div>`:''}<div class="profile-section"><div class="profile-section-title">Model context</div><div class="profile-context-grid"><div><span>Confidence</span><strong>${esc(conf(m.confidence))}</strong></div><div><span>Year 3 PPG</span><strong>${f(y3)}</strong></div><div><span>Career projected pts</span><strong>${career!=null?fi(career):'—'}</strong></div><div><span>Age</span><strong>${ageV!=null?f(ageV,0):'—'}</strong></div></div></div><div class="profile-section"><div class="profile-section-title">Analysis</div><div class="analysis-list">${notes.length?notes.map(x=>`<div class="analysis-item"><span>•</span><p>${esc(x)}</p></div>`).join(''):'<div class="muted">Not enough current data for analysis yet.</div>'}</div></div><div class="profile-source">Season PPG uses observed Sleeper season stats scored with this league's scoring settings. QB/RB/WR/TE projections remain Fantasy Model projections.</div></aside></div>`}
'''
