new = "function layout(title,body){return`<div class=\"shell ${st.nav?'nav-open':''}\"><aside class=\"sidebar\"><div class=\"brand\"><div class=\"brand-mark\">FM</div><div class=\"brand-copy\">Fantasy Model</div></div><button class=\"nav-toggle\" data-a=\"nav\">${st.nav?'← Collapse':'→'}</button><nav class=\"nav-list\">${nav('dashboard','▦','Dashboard')}${nav('live','◉','Live NFL Stats')}${nav('leaders','≡','NFL Leaders')}${nav('startsit','⚖','Start/Sit Tool')}<hr class=\"nav-separator\">${nav('about','ⓘ','About')}</nav></aside><main class=\"main\"><header class=\"topbar\"><div><h1>${esc(title)}</h1><div class=\"crumb\">${st.league?`${esc(st.league.name)} · ${esc(tname(me()?.roster_id))}`:'Fantasy Model'}</div></div><div class=\"top-actions\">${st.league?'<button class=\"btn btn-ghost\" data-a=\"refreshLeague\">Refresh league</button><button class=\"btn btn-ghost\" data-a=\"back\">All leagues</button>':''}<span class=\"pill\">${st.season} season</span></div></header><div class=\"content\">${body}</div></main></div>${playerProfile()}`}"
