new_roster = r'''function rosterTable(r,ids,opt){if(!ids.length)return'<div class="empty">No players found.</div>';const rows=ids.map(id=>{const p=st.players?.[id]||{},dst=isDstId(id,p),m=model(id,p),live=n(mi(r.roster_id)?.players_points?.[id],0),slot=opt.get(id),opp=m.opp||'Matchup unavailable',jersey=p.number||p.jersey_number,avgNote=m.avgSource==='actual'?(m.avgGames?`${m.avgGames} GP`:'Actual'):(m.avgSource==='projected'?'Projected':'');return{id,p,dst,m,live,slot,opp,jersey,avgNote}});const mobile=`<div class="mobile-player-list">${rows.map(x=>`<button class="mobile-player-card" data-player="${esc(x.id)}" data-roster="${r.roster_id}"><div class="mobile-player-top"><img class="mobile-player-image ${x.dst?'dst-logo':''}" src="${assetImage(x.id,x.p)}" alt="" onerror="this.style.visibility='hidden'"><div class="mobile-player-copy"><div class="mobile-player-name">${esc(pname(x.id))}</div><div class="player-meta">${esc(x.p.position||'—')} · ${esc(x.p.team||'FA')}${x.jersey?` · #${esc(x.jersey)}`:''}</div><div class="player-opp">${esc(x.opp)}</div></div><div class="mobile-card-action">›</div></div><div class="mobile-player-metrics"><div><span>Week ${st.week}</span><strong>${f(x.m.projection)}</strong></div><div><span>Season PPG</span><strong>${f(x.m.avg)}</strong><small>${esc(x.avgNote)}</small></div><div><span>Dynasty</span><strong>${x.m.dynasty!=null?fi(x.m.dynasty):'—'}</strong></div></div><div class="mobile-player-bottom"><span>${x.slot?`START · ${esc(x.slot)}`:'SIT'}</span><span>Live ${f(x.live)}</span><span>Range ${f(x.m.floor)}–${f(x.m.ceiling)}</span></div><div class="mobile-view-analysis">View player analysis</div></button>`).join('')}</div>`;const desktop=`<div class="roster-table-wrap desktop-roster-table"><table><thead><tr><th>Player</th><th>Projection</th><th>Live Fantasy</th><th>Floor</th><th>Ceiling</th><th>Season PPG</th><th>Dynasty</th><th>Lineup</th><th>Confidence</th></tr></thead><tbody>${rows.map(x=>`<tr><td><div class="player-cell player-open" data-player="${esc(x.id)}" data-roster="${r.roster_id}" role="button" tabindex="0"><img class="player-headshot ${x.dst?'dst-logo':''}" src="${assetImage(x.id,x.p)}" alt="" onerror="this.style.visibility='hidden'"><div><div class="player-name">${esc(pname(x.id))}</div><div class="player-meta">${esc(x.p.position||'—')} · ${esc(x.p.team||'FA')}${x.jersey?` · #${esc(x.jersey)}`:''}</div><div class="player-opp">${esc(x.opp)} · View analysis</div></div></div></td><td><strong>${f(x.m.projection)}</strong></td><td>${f(x.live)}</td><td>${f(x.m.floor)}</td><td>${f(x.m.ceiling)}</td><td><strong>${f(x.m.avg)}</strong>${x.avgNote?`<div class="cell-sub">${esc(x.avgNote)}</div>`:''}</td><td>${x.m.dynasty!=null?fi(x.m.dynasty):'—'}</td><td>${x.slot?`<span class="slot-label">START · ${esc(x.slot)}</span>`:'<span class="slot-label sit">SIT</span>'}</td><td>${esc(conf(x.m.confidence))}</td></tr>`).join('')}</tbody></table></div>`;return mobile+desktop}'''
