css += r'''

/* Web 1.3.1 — season-aware player cards and analysis drawer */
.mobile-player-list{display:none}.cell-sub{font-size:10px;color:var(--muted);margin-top:2px}.player-open{cursor:pointer;border-radius:10px;transition:.15s}.player-open:hover{background:rgba(182,255,69,.055)}.profile-backdrop{position:fixed;inset:0;z-index:80;background:rgba(0,0,0,.62);backdrop-filter:blur(5px);display:flex;justify-content:flex-end}.player-profile{width:min(560px,94vw);height:100%;overflow:auto;background:linear-gradient(180deg,#101713,#0b100d);border-left:1px solid var(--line);box-shadow:-24px 0 70px rgba(0,0,0,.38);padding:24px}.profile-grabber{display:none}.profile-head{display:grid;grid-template-columns:88px minmax(0,1fr) 38px;gap:15px;align-items:center;padding-bottom:20px;border-bottom:1px solid var(--line)}.profile-image{width:88px;height:88px;border-radius:18px;object-fit:cover;object-position:center 15%;background:#1a241f;border:1px solid var(--line)}.profile-image.dst-logo{object-fit:contain;padding:10px}.profile-title h2{margin:3px 0 5px;font-size:25px;letter-spacing:-.02em}.profile-close{align-self:start;width:36px;height:36px;border-radius:999px;border:1px solid var(--line);background:var(--panel2);font-size:24px;line-height:1;cursor:pointer}.profile-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:18px 0}.profile-metric{padding:13px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.018)}.profile-metric span,.profile-metric small{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.profile-metric strong{display:block;font-size:20px;margin:5px 0}.profile-metric small{text-transform:none;letter-spacing:0}.profile-section{border-top:1px solid var(--line);padding-top:16px;margin-top:16px}.profile-section-title{font-weight:850;margin-bottom:10px}.profile-stat-grid,.profile-context-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.profile-stat-grid>div,.profile-context-grid>div{padding:11px;border-radius:10px;background:var(--panel2);border:1px solid rgba(36,51,43,.8)}.profile-stat-grid span,.profile-context-grid span{display:block;color:var(--muted);font-size:10px;margin-bottom:4px}.profile-stat-grid strong,.profile-context-grid strong{font-size:16px}.analysis-list{display:grid;gap:8px}.analysis-item{display:grid;grid-template-columns:14px 1fr;gap:5px;padding:10px 12px;border-radius:10px;background:rgba(182,255,69,.045);border:1px solid rgba(182,255,69,.12)}.analysis-item span{color:var(--accent);font-weight:900}.analysis-item p{margin:0;color:#dce8df;font-size:13px;line-height:1.45}.profile-source{margin-top:18px;color:var(--muted);font-size:10px;line-height:1.45}
@media(max-width:900px){.desktop-roster-table{display:none}.mobile-player-list{display:grid;gap:10px}.mobile-player-card{display:block;width:100%;text-align:left;color:inherit;border:1px solid var(--line);border-radius:15px;background:linear-gradient(180deg,rgba(18,26,22,.98),rgba(13,19,16,.98));padding:13px;box-shadow:0 8px 24px rgba(0,0,0,.16);cursor:pointer}.mobile-player-card:active{transform:scale(.995);border-color:rgba(182,255,69,.36)}.mobile-player-top{display:grid;grid-template-columns:58px minmax(0,1fr) 22px;gap:11px;align-items:center}.mobile-player-image{width:58px;height:58px;border-radius:13px;object-fit:cover;object-position:center 15%;background:#1a241f;border:1px solid var(--line)}.mobile-player-image.dst-logo{object-fit:contain;padding:6px}.mobile-player-name{font-size:15px;font-weight:850}.mobile-card-action{font-size:28px;color:var(--accent);text-align:right}.mobile-player-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:11px}.mobile-player-metrics>div{padding:9px;border-radius:10px;background:rgba(255,255,255,.022);border:1px solid rgba(36,51,43,.78)}.mobile-player-metrics span,.mobile-player-metrics small{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.05em}.mobile-player-metrics strong{display:block;font-size:17px;margin-top:3px}.mobile-player-metrics small{text-transform:none;letter-spacing:0;margin-top:2px}.mobile-player-bottom{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px;color:var(--muted);font-size:10px}.mobile-player-bottom span:first-child{color:var(--accent);font-weight:800}.mobile-view-analysis{margin-top:10px;padding-top:9px;border-top:1px solid rgba(36,51,43,.75);color:var(--accent);font-size:11px;font-weight:800;text-align:right}.table-wrap{scrollbar-width:thin;box-shadow:inset -18px 0 18px -22px rgba(182,255,69,.75)}.table-wrap::before{content:'Swipe ↔ to see more';display:block;position:sticky;left:0;width:max-content;padding:6px 9px;color:var(--muted);font-size:10px;background:rgba(14,20,17,.92);border-bottom-right-radius:9px;z-index:3}.profile-backdrop{align-items:flex-end}.player-profile{align-self:flex-end;width:100%;height:min(86vh,760px);border-left:0;border-top:1px solid var(--line);border-radius:22px 22px 0 0;padding:12px 14px 24px;box-shadow:0 -24px 70px rgba(0,0,0,.45)}.profile-grabber{display:block;width:42px;height:4px;border-radius:99px;background:#435149;margin:0 auto 12px}.profile-head{grid-template-columns:72px minmax(0,1fr) 34px;gap:12px;padding-bottom:14px}.profile-image{width:72px;height:72px;border-radius:15px}.profile-title h2{font-size:21px}.profile-metrics{grid-template-columns:repeat(2,1fr);gap:7px;margin:13px 0}.profile-metric{padding:10px}.profile-metric strong{font-size:18px}.profile-stat-grid,.profile-context-grid{grid-template-columns:repeat(2,1fr)}.profile-section{margin-top:13px;padding-top:13px}}
'''
css_path.write_text(css, encoding='utf-8')

pkg = Path('web/package.json')
p = pkg.read_text(encoding='utf-8')
assert '"version": "1.3.0"' in p, 'web version anchor missing'
pkg.write_text(p.replace('"version": "1.3.0"','"version": "1.3.1"',1), encoding='utf-8')
